using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided facade piece cut from a surface.</summary>
    public class Panel
    {
        public Panel(Point3d a, Point3d b, Point3d c, Point3d d, int index)
        {
            Corners = new[] { a, b, c, d };
            Index = index;
            Outline = new PolylineCurve(new[] { a, b, c, d, a });
            Area = 0.5 * Vector3d.CrossProduct(c - a, d - b).Length;
            Deviation = ComputeDeviation(a, b, c, d);
        }

        public Point3d[] Corners { get; }
        public PolylineCurve Outline { get; }
        public double Area { get; }
        public double Deviation { get; }
        public int Index { get; }

        public Point3d Center => new Point3d(
            (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4.0,
            (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4.0,
            (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4.0);

        /// <summary>Length of edge i (0 = first corner to second, ..., 3 = fourth back to first).</summary>
        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        public double Diagonal(int i) => Corners[i].DistanceTo(Corners[i + 2]);

        /// <summary>Mean of first and third edge lengths.</summary>
        public double Width => 0.5 * (Edge(0) + Edge(2));

        /// <summary>Mean of second and fourth edge lengths.</summary>
        public double Height => 0.5 * (Edge(1) + Edge(3));

        private static double ComputeDeviation(Point3d a, Point3d b, Point3d c, Point3d d)
        {
            Vector3d n = Vector3d.CrossProduct(b - a, c - a);
            if (!n.Unitize())
                return 0.0;
            return Math.Abs((d - a) * n);
        }
    }
}
EOF
cat > Facade/PanelParam.cs <<'EOF'
using System;
using Grasshopper.Kernel;
using Grasshopper.Kernel.Types;

namespace BenchPlugin.Facade
{
    public class PanelGoo : GH_Goo<Panel>
    {
        public PanelGoo()
        {
        }

        public PanelGoo(Panel panel)
        {
            Value = panel;
        }

        public override bool IsValid => Value != null;
        public override string TypeName => "Panel";
        public override string TypeDescription => "Four-sided facade panel";

        public override IGH_Goo Duplicate() => new PanelGoo(Value);

        public override string ToString() => Value == null
            ? "Null Panel"
            : $"Panel {Value.Index} (area {Value.Area:0.###}, deviation {Value.Deviation:0.###})";

        public override bool CastFrom(object source)
        {
            if (source is Panel p)
            {
                Value = p;
                return true;
            }
            if (source is PanelGoo g)
            {
                Value = g.Value;
                return true;
            }
            return false;
        }
    }

    public class PanelParam : GH_Param<PanelGoo>
    {
        public PanelParam()
            : base("Panel", "Panel", "Facade panel", "Facade", "Params", GH_ParamAccess.item)
        {
        }

        public override Guid ComponentGuid => new Guid("c0a7e6f1-2b3d-4a58-9e41-6d1f8b7c2a01");
        public override GH_Exposure Exposure => GH_Exposure.hidden;
    }
}
EOF
cat > Facade/PanelComponent.cs <<'EOF'
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    /// <summary>Base for facade components: category "Facade" and panel parameter helpers.</summary>
    public abstract class PanelComponent : GH_Component
    {
        protected PanelComponent(string name, string nick, string description, string subCategory)
            : base(name, nick, description, "Facade", subCategory)
        {
        }

        protected static int AddPanelInput(GH_InputParamManager pManager, string description, GH_ParamAccess access)
        {
            return pManager.AddParameter(new PanelParam(), "Panels", "P", description, access);
        }

        protected static List<Panel> GetPanels(IGH_DataAccess DA, int index)
        {
            var goos = new List<PanelGoo>();
            if (!DA.GetDataList(index, goos))
                return new List<Panel>();
            return goos.Where(g => g != null && g.Value != null).Select(g => g.Value).ToList();
        }
    }
}
EOF
